def s(layout,title,copy='',features=None,metrics=None,eyebrow='',note='',inverse=False):
 d=dict(layout='ki-'+layout,title=title,copy=copy,eyebrow=eyebrow,note=note,inverse=inverse)
 if not note:d.pop('note')
 if features:d['features']=[dict(title=a,copy=b) for a,b in features]
 if metrics:d['metrics']=[dict(value=a,label=b) for a,b in metrics]
 return d
